mapper.select:
SELECT * FROM ( SELECT INNER_QUERY.*, ROWNUM AS RN FROM ( SELECT A.ACCOUNT_ID, A.ACCOUNT_NICKNAME, A.ACCOUNT_EMAIL, A.ACCOUNT_CONTACT, A.ACCOUNT_POST, A.ACCOUNT_ADDRESS1, A.ACCOUNT_ADDRESS2, A.ACCOUNT_JOIN, A.ACCOUNT_LOGIN, A.ACCOUNT_POINT, A.ACCOUNT_LEVEL, A.ACCOUNT_BLOCK FROM ACCOUNT A
AND A.ACCOUNT_ID = #{accountId}
AND A.ACCOUNT_NICKNAME = #{accountNickname}
AND A.ACCOUNT_EMAIL = #{accountEmailExact}
AND A.ACCOUNT_CONTACT = #{accountContact}
AND UPPER(A.ACCOUNT_EMAIL) LIKE '%' || UPPER(#{accountEmailLike}) || '%'
AND ( A.ACCOUNT_POST LIKE '%' || #{accountAddress} || '%' OR UPPER(A.ACCOUNT_ADDRESS1) LIKE '%' || UPPER(#{accountAddress}) || '%' OR UPPER(A.ACCOUNT_ADDRESS2) LIKE '%' || UPPER(#{accountAddress}) || '%' )
AND A.ACCOUNT_JOIN >= #{accountJoinBegin}
AND A.ACCOUNT_JOIN < #{accountJoinEnd} + 1
AND A.ACCOUNT_LOGIN >= #{accountLoginBegin}
AND A.ACCOUNT_LOGIN < #{accountLoginEnd} + 1
AND A.ACCOUNT_POINT >= #{accountPointMin}
AND A.ACCOUNT_POINT <= #{accountPointMax}
AND A.ACCOUNT_LEVEL IN
#{accountLevel}
AND A.ACCOUNT_BLOCK = #{accountBlock}
ORDER BY
A.ACCOUNT_ID
A.ACCOUNT_NICKNAME
A.ACCOUNT_EMAIL
A.ACCOUNT_LOGIN
A.ACCOUNT_POINT
A.ACCOUNT_LEVEL
A.ACCOUNT_JOIN
ASC
DESC
, A.ACCOUNT_ID DESC
) INNER_QUERY WHERE ROWNUM <= #{offset} + #{size} ) WHERE RN > #{offset}
